#!/usr/bin/env bash
# Aider による変更があれば作業ブランチへコミット・push し、PR を作成して Issue に通知する。
#   - 未追跡の新規ファイルも検出する（git diff ではなく git status を使用）
#   - Aider の作業ファイル（.aider*、自動生成した .aiderignore を含む）はコミットしない
#   - .github/workflows/ は GITHUB_TOKEN で push できないためコミットしない
#   - 最終テストが失敗した場合は Draft PR として作成する
#
# 入力（env）: GH_TOKEN, BASE_BRANCH, ISSUE_NUMBER, MODEL_NAME, TEST_COMMAND,
#              TEST_STATUS, ATTEMPTS, TARGET_FILES, RUN_URL, GITHUB_RUN_ID
# 出力（$GITHUB_OUTPUT）: pr_url
set -euo pipefail

: "${GH_TOKEN:?GH_TOKEN が未設定です}"
: "${BASE_BRANCH:?BASE_BRANCH が未設定です}"

PATHSPEC=(-- . ':(exclude).aider*' ':(exclude).github/workflows')
ISSUE_REF="${ISSUE_NUMBER:+#${ISSUE_NUMBER}}"

comment_issue() {
  if [ -n "${ISSUE_NUMBER:-}" ]; then
    gh issue comment "$ISSUE_NUMBER" --repo "$GITHUB_REPOSITORY" --body "$1"
  fi
}

if [ -z "$(git status --porcelain "${PATHSPEC[@]}")" ]; then
  echo "AI による変更はありませんでした。(No changes detected by AI)"
  echo "ℹ️ 変更なし: AI による変更はありませんでした。" >> "$GITHUB_STEP_SUMMARY"
  echo "pr_url=" >> "$GITHUB_OUTPUT"
  comment_issue "ℹ️ Gemini AI エージェントを実行しましたが、変更はありませんでした。[実行ログ](${RUN_URL})"
  exit 0
fi

skipped_workflows="$(git status --porcelain -- .github/workflows || true)"

branch="chore/ai-issue-${ISSUE_NUMBER:-manual}-${GITHUB_RUN_ID}"
git checkout -b "$branch"
git add -A "${PATHSPEC[@]}"
git commit \
  -m "chore(ai): ${ISSUE_REF:-手動実行} の自動修正 (Gemini)" \
  -m "Generated by Aider with gemini/${MODEL_NAME}.${ISSUE_REF:+ Refs ${ISSUE_REF}}"

# checkout は persist-credentials: false のため、push 時のみ gh の認証ヘルパーを使う
gh auth setup-git
git push -u origin "$branch"

case "${TEST_STATUS:-skipped}" in
  passed) test_line="✅ 成功 (\`${TEST_COMMAND}\`)" ;;
  failed) test_line="❌ 失敗 (\`${TEST_COMMAND}\`) — Draft PR として作成しました" ;;
  *) test_line="⏭️ 未実行（test_command 未指定）" ;;
esac

body_file="${RUNNER_TEMP:-/tmp}/aider/pr_body.md"
mkdir -p "$(dirname "$body_file")"
{
  echo "## 概要 (Summary)"
  echo ""
  echo "Gemini AI エージェント（Aider + \`gemini/${MODEL_NAME}\`）が ${ISSUE_REF:-手動実行} の指示に基づいて自動生成した変更です。"
  echo "マージ前に必ず人間がレビューしてください。"
  echo ""
  echo "| 項目 (Item) | 値 (Value) |"
  echo "| :--- | :--- |"
  echo "| 対象 Issue | ${ISSUE_REF:-なし} |"
  echo "| 対象ファイル指定 (Files) | ${TARGET_FILES:-なし（AI が判断）} |"
  echo "| 自動テスト (Test) | ${test_line} |"
  echo "| 試行回数 (Attempts) | ${ATTEMPTS:-1} |"
  echo "| 実行ログ (Run) | [${GITHUB_RUN_ID}](${RUN_URL}) |"
  if [ -n "$skipped_workflows" ]; then
    echo ""
    echo "> ⚠️ \`.github/workflows/\` への変更は GITHUB_TOKEN で push できないため除外しました。"
  fi
  echo ""
  echo "> ℹ️ GITHUB_TOKEN で作成した PR では CI が自動起動しません。CI を実行するには PR を一度 Close → Reopen してください。"
  if [ -n "${ISSUE_NUMBER:-}" ]; then
    echo ""
    echo "Refs #${ISSUE_NUMBER}"
  fi
} > "$body_file"

pr_args=(
  --repo "$GITHUB_REPOSITORY"
  --base "$BASE_BRANCH"
  --head "$branch"
  --title "chore(ai): ${ISSUE_REF:-手動実行} の自動修正 (Gemini)"
  --body-file "$body_file"
)
if [ "${TEST_STATUS:-}" = "failed" ]; then
  pr_args+=(--draft)
fi

pr_url="$(gh pr create "${pr_args[@]}")"
echo "PR を作成しました: ${pr_url}"
echo "pr_url=${pr_url}" >> "$GITHUB_OUTPUT"
echo "✅ PR を作成しました (Pull Request created): ${pr_url}" >> "$GITHUB_STEP_SUMMARY"

comment_issue "🤖 Gemini AI エージェントが PR を作成しました: ${pr_url}（自動テスト: ${test_line}）"
